/// <reference path="./manga-provider.d.ts" />

class Provider {
    private baseUrl = "https://mangafire.to";

    getSettings(): Settings {
        return {
            supportsMultiLanguage: false,
            supportsMultiScanlator: false,
        };
    }

    private async getJson(url: string): Promise<any> {
        const response = await fetch(url, {
            method: "GET",
            headers: {
                "Accept": "application/json",
                "Referer": this.baseUrl + "/",
            },
        });

        if (!response.ok) {
            throw new Error("MangaFire HTTP " + response.status);
        }

        return await response.json();
    }

    private getMangaId(value: string): string {
        const url = String(value || "").split("?")[0].replace(/\/+$/, "");
        const last = url.substring(url.lastIndexOf("/") + 1);

        if (url.indexOf("/title/") >= 0) {
            return last.split("-")[0];
        }

        if (url.indexOf("/manga/") >= 0) {
            const dot = last.lastIndexOf(".");
            if (dot >= 0) {
                return last.substring(dot + 1);
            }
        }

        return last;
    }

    async search(opts: QueryOptions): Promise<SearchResult[]> {
        const api =
            this.baseUrl +
            "/api/titles?keyword=" +
            encodeURIComponent(opts.query) +
            "&language=en&limit=30&page=1";

        const json = await this.getJson(api);
        const items = json && Array.isArray(json.items) ? json.items : [];
        const results: SearchResult[] = [];

        for (let i = 0; i < items.length; i++) {
            const item = items[i];

            if (!item || !item.url || !item.title) {
                continue;
            }

            const sourceUrl = String(item.url);
            const id = this.getMangaId(sourceUrl);

            if (!id) {
                continue;
            }

            const result: SearchResult = {
                id: id,
                title: String(item.title),
            };

            if (item.poster && item.poster.medium) {
                result.image = String(item.poster.medium);
            }

            results.push(result);
        }

        return results;
    }

    async findChapters(mangaId: string): Promise<ChapterDetails[]> {
        const id = this.getMangaId(mangaId);
        const chapters: ChapterDetails[] = [];
        const seen: { [key: string]: boolean } = {};

        const api =
            this.baseUrl +
            "/api/titles/" +
            encodeURIComponent(id) +
            "/chapters";

        let page = 1;
        let more = true;

        while (more && page <= 100) {
            const url =
                api +
                "?language=en&sort=number&order=desc&limit=200&page=" +
                page;

            const json = await this.getJson(url);
            const items = json && Array.isArray(json.items)
                ? json.items
                : [];

            for (let i = 0; i < items.length; i++) {
                const item = items[i];

                if (!item || item.id === undefined || item.id === null) {
                    continue;
                }

                const chapterId = String(item.id);

                if (seen[chapterId]) {
                    continue;
                }

                seen[chapterId] = true;

                let chapterNumber = "";
                if (item.number !== undefined && item.number !== null) {
                    chapterNumber = String(item.number);
                }

                let chapterTitle = "Chapter";
                if (chapterNumber !== "") {
                    chapterTitle = "Ch. " + chapterNumber;
                }

                if (item.name) {
                    chapterTitle =
                        chapterTitle + ": " + String(item.name);
                }

                chapters.push({
                    id: chapterId,
                    url:
                        this.baseUrl +
                        "/title/" +
                        encodeURIComponent(id) +
                        "/" +
                        encodeURIComponent(chapterId),
                    title: chapterTitle,
                    chapter: chapterNumber,
                    index: 0,
                });
            }

            more =
                !!json &&
                !!json.meta &&
                json.meta.hasNext === true;

            page++;
        }

        chapters.reverse();

        for (let i = 0; i < chapters.length; i++) {
            chapters[i].index = i;
        }

        return chapters;
    }

    async findChapterPages(chapterId: string): Promise<ChapterPage[]> {
        const json = await this.getJson(
            this.baseUrl +
            "/api/chapters/" +
            encodeURIComponent(String(chapterId))
        );

        const pages: ChapterPage[] = [];

        if (!json || !json.data || !Array.isArray(json.data.pages)) {
            return pages;
        }

        for (let i = 0; i < json.data.pages.length; i++) {
            const item = json.data.pages[i];

            if (!item || !item.url) {
                continue;
            }

            pages.push({
                url: String(item.url),
                index: pages.length,
                headers: {
                    "Referer": this.baseUrl,
                },
            });
        }

        return pages;
    }
}
